12	//
13	//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 起生效，登记结束 2026-03-31 00:00
14	//	新版 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版，2026-03-20 00:00 结束
15	//
16	// 查询时旧版的实际有效区间已被截断到 3 月 10 日。
17	var (
18		rngV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
19		rngV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
20		rngV2Start = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
21		rngV2End   = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
22	)
