24	func newRangeBook(t *testing.T) *Book {
25		t.Helper()
26		b := NewBook()
27		v1End := rngV1End
28		if err := b.RegisterVersion(RegisterRequest{
29			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
30			Start: rngV1Start, End: &v1End,
31		}); err != nil {
32			t.Fatalf("register seat-v1: %v", err)
33		}
34		v2End := rngV2End
35		if err := b.RegisterVersion(RegisterRequest{
36			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
37			Start: rngV2Start, End: &v2End, Replaces: "seat-v1",
38		}); err != nil {
39			t.Fatalf("register seat-v2: %v", err)
40		}
41		return b
42	}
