44	func rangeIDs(views []VersionView) []string {
45		ids := make([]string, len(views))
46		for i, v := range views {
47			ids[i] = v.VersionID
48		}
49		return ids
50	}
51	
52	func equalIDs(got []string, want ...string) bool {
53		if len(got) != len(want) {
54			return false
55		}
56		for i := range want {
57			if got[i] != want[i] {
58				return false
59			}
60		}
61		return true
62	}
