98	// 边界：范围含开始时刻、不含结束时刻；版本与范围仅在边界处相接不算命中。
99	func TestVersionsInRangeBoundaries(t *testing.T) {
100		b := newRangeBook(t)
101	
102		cases := []struct {
103			name string
104			from time.Time
105			to   time.Time
106			want []string
107		}{
108			// 范围结束即新版开始：只与旧版相交，新版只是相接。
109			{"范围结束即新版开始", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC), rngV2Start, []string{"seat-v1"}},
110			// 范围开始即新版开始：新版命中（开始时刻含）。
111			{"范围开始即新版开始", rngV2Start, time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC), []string{"seat-v2"}},
112			// 范围开始即新版结束：新版只是相接，不命中。
113			{"范围开始即新版结束", rngV2End, time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC), []string{}},
114			// 范围结束即新版结束：新版命中（结束时刻不含，但区间内仍有生效时间）。
115			{"范围结束即新版结束", time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC), rngV2End, []string{"seat-v2"}},
116			// 范围结束即旧版开始：旧版只是相接，不命中。
117			{"范围结束即旧版开始", time.Date(2026, 2, 20, 0, 0, 0, 0, time.UTC), rngV1Start, []string{}},
118			// 范围开始即旧版开始：旧版命中。
119			{"范围开始即旧版开始", rngV1Start, time.Date(2026, 3, 2, 0, 0, 0, 0, time.UTC), []string{"seat-v1"}},
120			// 交接点本身落在范围内：旧版实际区间止于交接点（不含），新版从交接点起（含），
121			// 范围跨过交接点时两版都命中。
122			{"范围跨过交接点", rngV2Start.Add(-time.Nanosecond), rngV2Start.Add(time.Nanosecond), []string{"seat-v1", "seat-v2"}},
123			// 单纳秒范围恰在交接点：只命中新版。
124			{"交接点上的单纳秒范围", rngV2Start, rngV2Start.Add(time.Nanosecond), []string{"seat-v2"}},
125			// 单纳秒范围恰在新版结束点：无命中。
126			{"新版结束点上的单纳秒范围", rngV2End, rngV2End.Add(time.Nanosecond), []string{}},
127		}
128		for _, c := range cases {
129			got, err := b.VersionsInRange("seat", c.from, c.to)
130			if err != nil {
131				t.Fatalf("%s: 不应报错, got %v", c.name, err)
132			}
133			if ids := rangeIDs(got); !equalIDs(ids, c.want...) {
134				t.Fatalf("%s: got %v, want %v", c.name, ids, c.want)
135			}
136		}
137	}
