452		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1") {
453			t.Fatalf("时钟在未来不影响查过去: %v", ids)
454		}
455	
456		// 时钟拨回登记之前，查未来的范围结论不变。
457		setNow(time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC))
458		got, err = b.VersionsInRange("seat",
459			time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
460			time.Date(2026, 3, 6, 0, 0, 0, 0, time.UTC))
461		if err != nil {
462			t.Fatal(err)
463		}
464		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1") {
465			t.Fatalf("时钟在过去不影响查未来: %v", ids)
466		}
467	}
468	
469	// 选择依据是查询时账本已登记的版本：补登过去生效的替代版本后，
470	// 同一历史范围的回答按当前登记的实际区间变化。
471	func TestVersionsInRangeReflectsRetroactiveRegistration(t *testing.T) {
472		b := NewBook()
473		v1End := rngV1End
474		if err := b.RegisterVersion(RegisterRequest{
475			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
476			Start: rngV1Start, End: &v1End,
477		}); err != nil {
